package com.example.planyourtrip.service;
import com.example.planyourtrip.dto.TimelineDto; import com.example.planyourtrip.exception.ApiException; import com.example.planyourtrip.model.*; import com.example.planyourtrip.repository.*; import org.springframework.http.HttpStatus; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional; import java.util.*;
@Service public class TimelineService { private final TimelineItemRepository repo; private final TripService tripService; private final PlaceRepository places; public TimelineService(TimelineItemRepository repo,TripService tripService,PlaceRepository places){this.repo=repo;this.tripService=tripService;this.places=places;} public List<TimelineDto> list(Long uid,Long tripId){tripService.ownerTrip(uid,tripId); return repo.findByTripOwnerIdAndTripId(uid,tripId).stream().map(this::toDto).toList();}
 @Transactional public TimelineDto create(Long uid,Long tripId,TimelineDto d){Trip trip=tripService.ownerTrip(uid,tripId); validate(trip,d); TimelineItem it=new TimelineItem(); it.setTrip(trip); apply(it,d); return toDto(repo.save(it));}
 @Transactional public TimelineDto update(Long uid,Long id,TimelineDto d){TimelineItem it=repo.findByIdAndTripOwnerId(id,uid).orElseThrow(()->new ApiException(HttpStatus.NOT_FOUND,"Timeline item not found")); validate(it.getTrip(),d); apply(it,d); return toDto(it);} @Transactional public void delete(Long uid,Long id){repo.delete(repo.findByIdAndTripOwnerId(id,uid).orElseThrow(()->new ApiException(HttpStatus.NOT_FOUND,"Timeline item not found")));}
 private void validate(Trip trip,TimelineDto d){ if(d.dayNumber()<1 || d.dayNumber()>trip.getEndDate().toEpochDay()-trip.getStartDate().toEpochDay()+1) throw new ApiException(HttpStatus.BAD_REQUEST,"Invalid timeline day number"); if(!d.startTime().isBefore(d.endTime())) throw new ApiException(HttpStatus.BAD_REQUEST,"startTime must be before endTime"); }
 private void apply(TimelineItem it,TimelineDto d){it.setDayNumber(d.dayNumber());it.setStartTime(d.startTime());it.setEndTime(d.endTime());it.setTitle(d.title());it.setNotes(d.notes()); it.setPlace(d.placeId()==null?null:places.findById(d.placeId()).orElse(null));}
 private TimelineDto toDto(TimelineItem it){return new TimelineDto(it.getId(),it.getTrip().getId(),it.getDayNumber(),it.getStartTime(),it.getEndTime(),it.getTitle(),it.getNotes(),it.getPlace()==null?null:it.getPlace().getId());}}
